import { AppbarContainer, AppShell, TabbarContainer } from '@app/ui';
import { NavBar } from '@src/components/navbar/NavBar';
import { ScriptCreatorContent } from '@src/components/page/script-creator/content/ScriptCreatorContent';
import { useTranslation } from 'react-i18next';

export default function ScriptCreatorPage() {
  const { t } = useTranslation('homepage/pages/script-creator/content');
  return (
    <AppShell>
      <AppbarContainer appbarProps={{ title: t('content.title'), back: true }}>
        <ScriptCreatorContent />
      </AppbarContainer>
    </AppShell>
  );
  return (
    <AppShell>
      <TabbarContainer
        titleConf={{ ns: 'homepage/pages/script-creator/content', key: 'content.title' }}
        navBar={<NavBar />}>
        <ScriptCreatorContent />
      </TabbarContainer>
    </AppShell>
  );
}
